photos = transpose(photos_raw)

categories = ["All", ...new Set(photos.map(d =&gt; d.category).filter(d =&gt; d))]

viewof cat = Inputs.radio(categories, {value: "All", label: "Show"})
viewof query = Inputs.search(photos, {
  placeholder: "Search captions, sites…",
  columns: ["caption", "site", "year"],
  label: "Filter"
})

shown = query.filter(d =&gt; cat === "All" || d.category === cat)





































viewof opened = {
  const wrap = html`&lt;div&gt;&lt;/div&gt;`;
  let current = null;

  const legend = d =&gt; [d.caption, d.site, d.year].filter(x =&gt; x && x !== "TODO")
    .join(" · ");

  const overlay = html`&lt;div class="photo-overlay" style="display:none"&gt;
    &lt;button class="photo-close" title="Close"&gt;&times;&lt;/button&gt;
    &lt;button class="photo-prev" title="Previous"&gt;&#8249;&lt;/button&gt;
    &lt;button class="photo-next" title="Next"&gt;&#8250;&lt;/button&gt;
    &lt;figure&gt;&lt;img src=""&gt;&lt;figcaption&gt;&lt;/figcaption&gt;&lt;/figure&gt;
  &lt;/div&gt;`;

  const img = overlay.querySelector("img");
  const cap = overlay.querySelector("figcaption");

  function show(i) {
    current = (i + shown.length) % shown.length;
    const d = shown[current];
    img.src = d.path;
    cap.textContent = legend(d);
    overlay.style.display = "flex";
  }
  function hide() { overlay.style.display = "none"; current = null; }

  overlay.querySelector(".photo-close").onclick = hide;
  overlay.querySelector(".photo-prev").onclick = e =&gt; { e.stopPropagation(); show(current - 1); };
  overlay.querySelector(".photo-next").onclick = e =&gt; { e.stopPropagation(); show(current + 1); };
  overlay.onclick = e =&gt; { if (e.target === overlay) hide(); };
  d3.select(document.body).on("keydown.gallery", e =&gt; {
    if (current === null) return;
    if (e.key === "Escape") hide();
    if (e.key === "ArrowRight") show(current + 1);
    if (e.key === "ArrowLeft") show(current - 1);
  });

  const grid = html`&lt;div class="photo-grid"&gt;
    ${shown.map((d, i) =&gt; {
      const fig = html`&lt;figure&gt;
        &lt;img src="${d.path}" alt="${d.caption}" loading="lazy"&gt;
        &lt;figcaption&gt;${legend(d)}&lt;/figcaption&gt;
      &lt;/figure&gt;`;
      fig.onclick = () =&gt; show(i);
      return fig;
    })}
  &lt;/div&gt;`;

  wrap.append(grid, overlay);
  wrap.value = null;
  return wrap;
}







html`&lt;p class="figure-caption"&gt;${shown.length} of ${photos.length} photographs.
Click any image to open it; use the arrow keys to move through the set.&lt;br&gt;
All photographs © Kauan Fonseca. Please ask before reusing them.&lt;/p&gt;`
